export default function next({values,previousState}) {
  if(!Array.isArray(values))throw Error('Invalid sheet values');
  if(!values.length)return {state:{index:0},more:false,chatId:'0',count:0,wait:false};
  const header=values[0];if(!Array.isArray(header)||header[0]!=='Chat ID')throw Error('The first column must be headed Chat ID');
  const rows=values.slice(1).filter(r=>Array.isArray(r)&&r.some(v=>v!==''&&v!=null));
  const i=previousState?.index??0;if(!Number.isInteger(i)||i<0||i>rows.length)throw Error('Invalid progress');
  if(i===rows.length)return {state:{index:i},more:false,chatId:'0',count:i,wait:false};
  const id=rows[i][0];if((typeof id!=='string'&&typeof id!=='number')||!String(id).trim())throw Error('Every recipient needs a Chat ID');
  return {state:{index:i+1},more:true,chatId:String(id).trim(),count:i+1,wait:((i+1)%30===0||i+1===rows.length)};
}
